import{_ as t,c as n,j as e,a as l,o as r}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第九十二章 指甲尖上的尘土多吗？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/92第九十二章 指甲尖上的尘土多吗.md","filePath":"meditation/巴利文大藏经/92第九十二章 指甲尖上的尘土多吗.md"}'),_={name:"meditation/巴利文大藏经/92第九十二章 指甲尖上的尘土多吗.md"};function o(s,a,i,d,p,c){return r(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第九十二章-指甲尖上的尘土多吗",tabindex:"-1"},[l("第九十二章 指甲尖上的尘土多吗？ "),e("a",{class:"header-anchor",href:"#第九十二章-指甲尖上的尘土多吗","aria-label":'Permalink to "第九十二章 指甲尖上的尘土多吗？"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"13.(2).现观相应",-1),e("p",null,"相应部13相应1经/指甲尖经(现观相应/因缘篇/如来记说)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀用手指头上的指甲轻轻的在大地上沾了少量的尘土后，就对出家弟子们说：“弟子们，你们看看，如来指甲尖上沾的尘土多，还是大地上的尘土多？”",-1),e("p",null,"出家弟子们回答：“世尊，大地上的尘土更多，世尊指甲尖上沾的尘土少，世尊您指甲尖上沾的尘土实在是比不上大地尘土的百分之一、千分之一、十万分之一。世尊，我们估计大地尘土是无限多的，无法具体的说出您指甲尖上沾的尘土是大地尘土的多少分之一，所以就只好说出了百分之一、千分之一、十万分之一这些表示惊讶的虚拟词语，实际上大地尘土是无法估量出具体有多少的，您指甲尖上的尘土如果要与大地的尘土相比的话，基本上可以忽略不计。”",-1),e("p",null,"佛陀说：“弟子们，同样的道理，具足正确见解，已经证悟初果（初果解释，见第七十章）及以上果位的圣弟子们，他们灭尽、灭除的烦恼和痛苦很多，他们灭尽的烦恼和痛苦就如同大地尘土那么多，他们残留的烦恼和痛苦非常的少，他们残留的烦恼和痛苦就如同如来指甲尖上沾的尘土那么少。弟子们，也就是说已经证悟初果的圣弟子们，他们灭尽、灭除的烦恼和痛苦非常的多，残留的烦恼和痛苦非常的少，如果要进行比较的话，他们证悟初果之后残留的烦恼和痛苦是证悟初果之前烦恼和痛苦的百分之一、千分之一、十万分之一，当然就如同你们刚才所说的那样，百分之一、千分之一、十万分之一这些只是表示惊讶的虚拟词，实际上他们证悟初果后残留的烦恼和痛苦与证悟初果之前具有的烦恼和痛苦相比，基本上可以忽略不计。这些已经证悟初果的圣弟子们，他们最多在人间和天界往返七次，就能永远的从生死轮回中解脱出来，也就是说已经证悟初果的圣弟子们，他们最多再有七次的生死轮回，就能除灭一切的烦恼和痛苦，就能从这个世间永远的解脱出来，就能从生死轮回中永远的解脱出来。弟子们，具足正确的见解，证悟初果就能获得这么大的功德利益，明白了如来所说的正法，就能获得这么大的功德利益。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(_,[["render",o]]);export{u as __pageData,f as default};
